param([string]$Path)

$values = @(1, 2, 3)
$options = @{ Path = $Path; Raw = $true }
Get-Content @options | Write-Output
$value = [System.IO.File]::ReadAllText($Path)
$length = $value.Length
Write-Output "value: $value"
Write-Output '$value'

if ($length -gt 0) {
    Write-Output $value
} else {
    Write-Output 'empty'
}

foreach ($item in $values) {
    Write-Output $item
}

$count = 0
++${count}
--${count}
${count}++
${count}--

for ($i = 0; $i -lt 3; $i++) {
    Write-Output $i
}
for (; $count -lt 3;) {
    ++${count}
}
for (;;) {
    break
}

do {
    $count++
} until ($count -ge 3)

switch ($count) {
    1 { Write-Output 'one' }
    'two' { Write-Output 'two' }
    { $_ -gt 2 } { Write-Output 'many' }
    default { Write-Output 'other' }
}
switch -Regex -CaseSensitive ($value) {
    '^a' { Write-Output 'a' }
}
